use crate::rng::Rng;

pub(crate) struct Prior {
    pub low: f64,
    pub high: f64,
    intercept: f64,
    slope: f64,
    knots: [f64; 33],
}

impl Prior {
    pub fn sample(&self, seed: u64, label: &str, speed: f64) -> f64 {
        Rng::for_label(seed, label).truncated(self.low, self.high, |rng| {
            let position = rng.unit() * 32.0;
            let index = (position.floor() as usize).min(31);
            let residual = self.knots[index] + (self.knots[index + 1] - self.knots[index]) * (position - index as f64);
            self.intercept + self.slope * speed + residual
        })
    }
}

